mapper.select:
SELECT m.id, m.session_id, m.role, m.content, m.tool_name, m.tool_call_id,
       m.priority, m.token_count, m.created_at
FROM chat_message m
INNER JOIN chat_session s ON s.id = m.session_id
WHERE m.session_id = #{sessionId}
  AND s.user_id = #{userId}
ORDER BY m.id DESC
    LIMIT #{limit}
